[ -n "$WF" ] && python3 -c '
import sys, yaml
d = yaml.safe_load(open(sys.argv[1]))
steps = d["jobs"]["governance-check"]["steps"]
sys.exit(0 if any("profile --run" in (s.get("run") or "") and (s.get("env") or {}).get("GH_TOKEN") == "${{ github.token }}" for s in steps) else 1)' "$WF" 2>/dev/null && ok "the landed governance workflow exports GH_TOKEN on the profile step (scm-protection can see the server at ci)" || bad "landed workflow does not export GH_TOKEN on the profile step" "$WF"
OUT=$(cd "$P" && python3 scripts/gate.py scm-protection 2>&1); RC=$?
[ "$RC" -eq 0 ] && printf '%s' "$OUT" | grep -q 'n/a' && printf '%s' "$OUT" | grep -q 'cannot see the server' && ok "scm-protection at the push: n/a — a local clone cannot see the server (verified at ci)" || bad "scm-protection at push wrong (rc=$RC)" "$OUT"
OUT=$(cd "$P" && env -u GITHUB_TOKEN -u GH_TOKEN -u GITHUB_ACTIONS python3 scripts/gate.py scm-protection --control-point ci 2>&1); RC=$?
[ "$RC" -eq 0 ] && printf '%s' "$OUT" | grep -q 'no GITHUB_TOKEN' && printf '%s' "$OUT" | grep -q 'checklist:' && ok "scm-protection at ci without a token: n/a with the checklist, never a silent green" || bad "scm-protection at ci wrong (rc=$RC)" "$OUT"
OUT=$(cd "$P" && env -u GITHUB_TOKEN -u GH_TOKEN GITHUB_ACTIONS=true python3 scripts/gate.py scm-protection --control-point ci 2>&1); RC=$?
[ "$RC" -eq 1 ] && printf '%s' "$OUT" | grep -q 'does not export it' && ok "scm-protection on a runner that has a token and hides it: RED — a wiring finding, never n/a" || bad "scm-protection on a token-hiding runner wrong (rc=$RC)" "$OUT"
OUT=$(cd "$P" && env -u GITHUB_TOKEN -u GH_TOKEN -u GITHUB_ACTIONS python3 scripts/gate.py scm-protection --control-point ci --json 2>&1 | python3 -c 'import json,sys; d=json.load(sys.stdin); print(d["status"], len(d["checklist"]))')
[ "$OUT" = "n/a 5" ] && ok "the five settings every host expresses are the checklist the JSON carries" || bad "scm-protection json wrong" "$OUT"
OUT=$(cd "$P" && python3 scripts/gate.py seal --check --control-point static --base origin/main 2>&1); RC=$?
[ "$RC" -eq 0 ] && printf '%s' "$OUT" | grep -q 'advisory' && printf '%s' "$OUT" | grep -qF "owed now: $(printf '%s' "$SEALG" | sed 's/,/, /g')" && ok "at the static round the seal is advisory: it names what the loop will owe, never a blocker before the loop ran" || bad "static seal not advisory (rc=$RC)" "$OUT"
MISSING=$(cd "$P" && python3 -c "
import json; d=json.load(open('.claude/settings.json')); import os
scripts=[t for g in d['hooks'].values() for grp in g for h in grp['hooks'] for t in h['command'].split() if t.endswith('.sh')]
print(' '.join(t for t in scripts if not (os.path.isfile(t) and os.access(t, os.X_OK))))")
[ -z "$MISSING" ] && ok "every hook wired in settings.json is delivered and executable" || bad "hooks wired but not delivered/executable: $MISSING"
# EVOL-063 — the compaction window ships with the settings
OUT=$(cd "$P" && python3 -c "import json; v=json.load(open('.claude/settings.json')).get('autoCompactWindow'); print(type(v).__name__, v)" 2>&1)
[ "$OUT" = "int 300000" ] && ok "settings.json ships the compaction window (autoCompactWindow 300000)" || bad "autoCompactWindow not shipped" "$OUT"
# EVOL-064 — the vertical-slicing body left CLAUDE.md: the rule lands and binds where increments are planned
OUT=$(cd "$P" && python3 scripts/gate.py applicable --paths docs/spec/FEAT-1/increment_plan.md --format json 2>&1 | python3 -c "import json,sys; print(' '.join(r['name'] for r in json.load(sys.stdin)['active']['rules']))" 2>&1)
[ -f "$P/.claude/rules/vertical-slicing.md" ] && [[ " $OUT " == *" vertical-slicing.md "* ]] && ok "rules/vertical-slicing.md lands and applies to an increment plan" || bad "vertical-slicing rule not delivered or not applicable" "$OUT"
OUT=$(cd "$P" && bash scripts/validate-governance.sh --banner 2>&1)
printf '%s' "$OUT" | grep -q 'Governance loaded: constitution' && ok "session banner: $OUT" || bad "banner wrong" "$OUT"

# EVOL-062 — the context diet on the materialised tree: a worker resolves under its cap, the Stop hook records and never holds, the banner names the hand-off
OUT=$(cd "$P" && python3 scripts/gate.py agents --resolve --class worker --files 1 --lines 1 --json 2>&1); RC=$?
[ "$RC" -eq 0 ] && [ "$(printf '%s' "$OUT" | python3 -c 'import json,sys; print(json.load(sys.stdin).get("turn_cap"))' 2>/dev/null)" = "80" ] && ok "a worker resolves under its cap (agents.worker_turn_cap)" || bad "worker cap not resolved (rc=$RC)" "$OUT"
mkdir -p "$P/.claude/state"
OUT=$(cd "$P" && printf '%s' '{"session_id":"smoke","stop_hook_active":false}' | CLAUDE_PROJECT_DIR="$P" bash .claude/hooks/session-handoff.sh 2>&1); RC=$?
[ "$RC" -eq 0 ] && [ -z "$OUT" ] && ok "the Stop hook outside a sub-increment: exit 0, silent" || bad "session-handoff wrong (rc=$RC)" "$OUT"
HB=$(git -C "$P" rev-parse --abbrev-ref HEAD); HS=$(git -C "$P" rev-parse HEAD)
printf '{"branch":"%s","train":null,"head":"%s","clean":true,"pushed":true,"closed":true,"at":"2026-01-01T00:00:00Z"}\n' "$HB" "$HS" > "$P/.claude/state/handoff.json"
OUT=$(cd "$P" && bash scripts/validate-governance.sh --banner 2>&1); rm -f "$P/.claude/state/handoff.json"
printf '%s' "$OUT" | grep -q "hand-off: $HB closed at ${HS:0:8}" && ok "the banner names the hand-off recorded for the current branch" || bad "banner without the hand-off" "$OUT"

# #114 — QA-PRE-1 from the template: the allowlist seeded from the fixture's Q26 answers; an allowlisted project
# passes, a denied dependency blocks. The stack answers (Q5 / Q9) pick the readers.
D="$SCRATCH/deps"; mkdir -p "$D/docs" "$D/config"; cp -R "$P/scripts" "$D/scripts"; cp "$P/docs/constitution.md" "$D/docs/"; cp "$P/config/allowlist.json" "$D/config/"
python3 - "$ANSWERS" "$D" <<'PY'
import json, sys
from pathlib import Path
A, D = json.loads(Path(sys.argv[1]).read_text())["answers"], Path(sys.argv[2])
tree = {}
for k, v in A.items():
    *head, last = k.split("."); node = tree
    for h in head: node = node.setdefault(h, {})
    node[last] = v
def y(d, ind=0):
    return "".join(f"{'  ' * ind}{k}:\n{y(v, ind + 1)}" if isinstance(v, dict) else f"{'  ' * ind}{k}: {json.dumps(v)}\n" for k, v in d.items())
(D / "docs/setup.md").write_text("---\n" + y(tree) + "---\n", encoding="utf-8")
(D / "pyproject.toml").write_text('[project]\nname = "app"\ndependencies = ["fastapi>=0.110"]\n', encoding="utf-8")
(D / "uv.lock").write_text('[[package]]\nname = "fastapi"\nversion = "0.115.2"\n', encoding="utf-8")
(D / "web").mkdir()
(D / "web/package.json").write_text(json.dumps({"dependencies": {"react": "^18.2.0"}}), encoding="utf-8")
(D / "web/package-lock.json").write_text(json.dumps({"lockfileVersion": 3, "packages": {"": {}, "node_modules/react": {"version": "18.3.1"}}}), encoding="utf-8")
PY
OUT=$(cd "$D" && env -u CLAUDE_PROJECT_DIR python3 scripts/gate.py --repo "$D" dependencies --seed 2>&1 && env -u CLAUDE_PROJECT_DIR bash scripts/dependency-allowlist.sh --strict 2>&1); RC=$?
[ "$RC" -eq 0 ] && ok "QA-PRE-1 from the template: seeded from Q26, an allowlisted project passes" || bad "allowlisted project not green (rc=$RC)" "$OUT"
python3 -c 'import json,sys; p=sys.argv[1]; d=json.load(open(p)); d["dependencies"]["moment"]="2.30.1"; json.dump(d,open(p,"w"))' "$D/web/package.json"
python3 -c 'import json,sys; p=sys.argv[1]; d=json.load(open(p)); d["packages"]["node_modules/moment"]={"version":"2.30.1"}; json.dump(d,open(p,"w"))' "$D/web/package-lock.json"
OUT=$(cd "$D" && env -u CLAUDE_PROJECT_DIR bash scripts/dependency-allowlist.sh --strict 2>&1); RC=$?
[ "$RC" -eq 1 ] && printf '%s' "$OUT" | grep -q 'moment is denied' && ok "QA-PRE-1 from the template: a denied dependency blocks (exit 1, named)" || bad "denied dependency not red (rc=$RC)" "$OUT"

echo; echo "materialize-synthetic: $PASS passed, $FAIL failed"
[ "${MATERIALIZE_KEEP:-0}" = "1" ] && echo "scratch kept at $P"
[ "$FAIL" -eq 0 ]
